from collections import OrderedDict

class Solution:
    def lru(self, capacity: int, operations: list[list]) -> list:
        cache=OrderedDict()
        outputs=[]
        for op in operations:
            if op[0]=="put":
                cache[op[1]]=op[2]
                cache.move_to_end(op[1])
                if len(cache)>capacity:cache.popitem(last=False)
            else:
                outputs.append(cache.get(op[1]))
                if op[1] in cache:cache.move_to_end(op[1])
        return outputs

